import React, { useState } from 'react';
import SimpleEditor from './SimpleEditor';

const RULED = 'repeating-linear-gradient(transparent, transparent 24px, rgba(100,80,50,0.055) 24px, rgba(100,80,50,0.055) 25px)';

function subjectCode(id) {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (Math.imul(31, h) + id.charCodeAt(i)) | 0;
  return `MU-${String(Math.abs(h % 9999) + 1).padStart(4, '0')}`;
}

function CopyBtn({ text, label = 'COPY REPORT' }) {
  const [copied, setCopied] = useState(false);
  return (
    <button onClick={() => { navigator.clipboard?.writeText(text); setCopied(true); setTimeout(() => setCopied(false), 1500); }}
      style={{ fontSize: 8, padding: '3px 10px', borderRadius: 2, border: '1px solid var(--paper-3)', color: copied ? 'var(--green)' : 'var(--ink-4)', background: 'transparent', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.07em' }}>
      {copied ? '✓ COPIED' : label}
    </button>
  );
}

function FieldNoteCard({ thought, book, thoughtTypes, onDetach }) {
  const typeInfo = (thoughtTypes || []).find(t => t.id === thought.type) || { color: '#7a6a52', bg: '#f0e8d8', label: thought.type || 'note' };
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';

  return (
    <div style={{
      background: isDark ? '#241e14' : '#fefcf5',
      backgroundImage: RULED,
      border: `1px solid var(--paper-3)`,
      borderLeft: `3px solid ${typeInfo.color}`,
      borderRadius: 2,
      padding: '10px 12px',
      marginBottom: 8,
      position: 'relative',
      boxShadow: '0 1px 4px rgba(100,70,20,0.07)',
    }}>
      {/* Classification stamp */}
      <div style={{ position: 'absolute', top: 6, right: 8, fontSize: 7, color: typeInfo.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.1em', opacity: 0.65, transform: 'rotate(-5deg)', borderBottom: `1px solid ${typeInfo.color}55`, paddingBottom: 1 }}>
        {typeInfo.label?.toUpperCase().slice(0, 4)}.
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 6, paddingRight: 48, flexWrap: 'wrap' }}>
        <div style={{ width: 5, height: 5, borderRadius: '50%', background: book?.color || '#888', flexShrink: 0 }} />
        <span style={{ fontSize: 10, color: book?.color || 'var(--ink-3)', fontStyle: 'italic' }}>{book?.title}</span>
        {thought.page && <span style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>p.{thought.page}</span>}
        <button onClick={() => onDetach(thought.id)} style={{ marginLeft: 'auto', fontSize: 9, color: 'var(--ink-4)', padding: '0 2px', cursor: 'pointer', background: 'none', border: 'none' }}
          onMouseEnter={e => e.currentTarget.style.color = 'var(--red)'}
          onMouseLeave={e => e.currentTarget.style.color = 'var(--ink-4)'}>✕</button>
      </div>

      {thought.quote && (
        <blockquote style={{ borderLeft: '2px solid var(--paper-3)', paddingLeft: 10, margin: '0 0 6px', fontSize: 12, color: 'var(--ink-2)', fontStyle: 'italic', lineHeight: 1.65, background: 'none', borderRadius: 0 }}>
          "{thought.quote}"
        </blockquote>
      )}
      <div style={{ fontSize: 13, color: 'var(--ink)', lineHeight: 1.65 }}
        dangerouslySetInnerHTML={{ __html: thought.text || '' }} />
    </div>
  );
}

export default function TopicPage({ topic, thoughts, books, allThoughts, thoughtTypes, onUpdate, onDelete, onBack, onCreateSubTopic }) {
  const [editingTitle, setEditingTitle] = useState(false);
  const [titleDraft, setTitleDraft]     = useState(topic.title);
  const [showAttachPicker, setShowAttachPicker] = useState(false);
  const [attachSearch, setAttachSearch] = useState('');
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';

  const attachedThoughts = thoughts;
  const bookIds  = [...new Set(attachedThoughts.map(t => t.bookId))];
  const byBook   = bookIds.map(bid => ({ book: books.find(b => b.id === bid), thoughts: attachedThoughts.filter(t => t.bookId === bid) }));
  const unattached = allThoughts.filter(t =>
    !topic.thoughtIds.includes(t.id) &&
    (attachSearch === '' || t.text?.toLowerCase().includes(attachSearch.toLowerCase()) || t.topics?.some(tp => tp.includes(attachSearch.toLowerCase())))
  );

  const handleTitleSave    = () => { setEditingTitle(false); if (titleDraft.trim()) onUpdate({ ...topic, title: titleDraft.trim() }); };
  const handleSummaryChange = (val) => onUpdate({ ...topic, summary: val });
  const handleEssayChange   = (val) => onUpdate({ ...topic, essay: val });
  const handleDetach  = (id) => onUpdate({ ...topic, thoughtIds: topic.thoughtIds.filter(tid => tid !== id) });
  const handleAttach  = (id) => { onUpdate({ ...topic, thoughtIds: [...topic.thoughtIds, id] }); setAttachSearch(''); };
  const code = subjectCode(topic.id);

  const buildExportText = () => {
    const lines = [`SUBJECT FILE — ${topic.title}`, `REF: ${code}`, ''];
    if (topic.summary) lines.push('THESIS:', topic.summary, '');
    if (topic.essay) {
      const plain = topic.essay.replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
      if (plain) lines.push('ANALYSIS:', plain, '');
    }
    if (attachedThoughts.length) {
      lines.push('FIELD NOTES FROM SOURCES:', '');
      byBook.forEach(({ book, thoughts: bThoughts }) => {
        lines.push(`[ ${book?.title || 'Unknown'} ]`);
        bThoughts.forEach(t => { if (t.quote) lines.push(`> "${t.quote}"`); lines.push(t.text || ''); lines.push(''); });
      });
    }
    return lines.join('\n');
  };

  const lastUpdated = new Date(topic.updatedAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', background: isDark ? '#18140e' : '#f5f0e4', fontFamily: 'var(--font-serif)' }}>

      {/* ── SUBJECT FILE HEADER ─────────────────────────── */}
      <div style={{ padding: '12px 22px 10px', borderBottom: '2px solid var(--paper-3)', flexShrink: 0, background: isDark ? '#1c1914' : '#e8dfc8', position: 'relative', overflow: 'hidden' }}>
        {/* Faint compass watermark */}
        <div style={{ position: 'absolute', right: 20, top: '50%', transform: 'translateY(-50%)', fontSize: 80, color: 'var(--accent-2)', opacity: 0.05, fontFamily: 'var(--font-display)', pointerEvents: 'none', userSelect: 'none', lineHeight: 1 }}>◊</div>

        {/* Top line — classification */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
          <button onClick={onBack}
            style={{ fontSize: 8, color: 'var(--ink-4)', cursor: 'pointer', background: 'none', border: '1px solid var(--paper-3)', borderRadius: 2, padding: '2px 9px', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.08em' }}
            onMouseEnter={e => e.currentTarget.style.borderColor = 'var(--accent-2)'}
            onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--paper-3)'}>
            ← CATALOGUE
          </button>
          <span style={{ fontSize: 8, color: 'var(--accent)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.12em', opacity: 0.8 }}>{code}</span>
          {topic.parentId && <span style={{ fontSize: 7, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.1em', textTransform: 'uppercase', border: '1px solid var(--paper-3)', padding: '0px 6px', borderRadius: 2 }}>SUB-FILE</span>}
          <div style={{ flex: 1 }} />
          <span style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.06em' }}>
            LAST UPDATED: {lastUpdated}
          </span>
          <CopyBtn text={buildExportText()} />
          <div style={{ display: 'flex', gap: 5 }}>
            {onCreateSubTopic && !topic.parentId && (
              <button onClick={() => onCreateSubTopic(topic.id)}
                style={{ fontSize: 8, padding: '3px 10px', borderRadius: 2, border: '1px solid var(--paper-3)', color: 'var(--ink-3)', background: 'transparent', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.07em' }}>
                + SUB-FILE
              </button>
            )}
            <button onClick={() => { if (window.confirm('Delete this subject file?')) onDelete(topic.id); }}
              style={{ fontSize: 8, padding: '3px 10px', borderRadius: 2, border: '1px solid var(--paper-3)', color: 'var(--ink-4)', background: 'transparent', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.07em' }}
              onMouseEnter={e => { e.currentTarget.style.color = 'var(--red)'; e.currentTarget.style.borderColor = 'var(--red)'; }}
              onMouseLeave={e => { e.currentTarget.style.color = 'var(--ink-4)'; e.currentTarget.style.borderColor = 'var(--paper-3)'; }}>
              DESTROY
            </button>
          </div>
        </div>

        {/* Subject title — editable Playfair Display */}
        <div style={{ height: 1, background: 'var(--paper-3)', marginBottom: 8 }} />
        {editingTitle ? (
          <input autoFocus value={titleDraft} onChange={e => setTitleDraft(e.target.value)} onBlur={handleTitleSave} onKeyDown={e => e.key === 'Enter' && handleTitleSave()}
            style={{ fontSize: 20, fontFamily: 'var(--font-display)', fontWeight: 700, fontStyle: 'italic', border: 'none', background: 'transparent', outline: '1px dashed var(--accent-2)', color: 'var(--ink)', width: '100%', letterSpacing: '0.01em' }} />
        ) : (
          <div onClick={() => setEditingTitle(true)} title="Click to rename"
            style={{ fontSize: 20, fontFamily: 'var(--font-display)', fontWeight: 700, fontStyle: 'italic', color: 'var(--ink)', cursor: 'text', letterSpacing: '0.01em', lineHeight: 1.25 }}>
            {topic.title}
          </div>
        )}

        {/* Source dots */}
        {byBook.length > 0 && (
          <div style={{ display: 'flex', gap: 6, marginTop: 7, alignItems: 'center', flexWrap: 'wrap' }}>
            <span style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.08em' }}>SOURCES:</span>
            {byBook.map(({ book }) => book && (
              <span key={book.id} style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: 10, color: book.color, fontStyle: 'italic' }}>
                <div style={{ width: 6, height: 6, borderRadius: '50%', background: book.color, boxShadow: `0 0 0 1.5px ${book.color}44` }} />
                {book.title}
              </span>
            ))}
            <span style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginLeft: 'auto' }}>
              {attachedThoughts.length} field note{attachedThoughts.length !== 1 ? 's' : ''}
            </span>
          </div>
        )}
      </div>

      {/* ── BODY — two columns ──────────────────────────── */}
      <div style={{ flex: 1, overflow: 'hidden', display: 'grid', gridTemplateColumns: '1fr 1fr' }}>

        {/* LEFT — synthesis (ruled paper) */}
        <div style={{ overflow: 'auto', borderRight: '1px solid var(--paper-3)', padding: '20px 24px', background: isDark ? '#1c1810' : '#faf6ee' }}>

          {/* Memo header */}
          <div style={{ display: 'flex', gap: 12, marginBottom: 16, paddingBottom: 10, borderBottom: '1px dashed var(--paper-3)', flexWrap: 'wrap' }}>
            <div style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.07em' }}>RE: {topic.title}</div>
            <div style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.07em' }}>REF: {code}</div>
            <div style={{ marginLeft: 'auto', fontSize: 8, color: 'var(--accent-2)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.1em' }}>SYNTHESIS FILE</div>
          </div>

          {/* Thesis */}
          <div style={{ marginBottom: 18 }}>
            <div style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.12em', textTransform: 'uppercase', marginBottom: 8 }}>
              Central thesis
            </div>
            <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start' }}>
              <textarea value={topic.summary || ''} onChange={e => handleSummaryChange(e.target.value)}
                placeholder="The core idea this subject is circling — rerum cognoscere causas…" rows={2}
                style={{ flex: 1, resize: 'vertical', padding: '7px 10px', fontSize: 13, lineHeight: 1.7, fontStyle: 'italic', color: 'var(--ink-2)', border: '1px solid var(--paper-3)', borderRadius: 2, background: 'transparent', fontFamily: 'var(--font-serif)', outline: 'none', backgroundImage: RULED }} />
              {topic.summary && <CopyBtn text={topic.summary} label="COPY" />}
            </div>
          </div>

          {/* Essay */}
          <div>
            <div style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.12em', textTransform: 'uppercase', marginBottom: 8 }}>
              Extended analysis
            </div>
            <SimpleEditor value={topic.essay || ''} onChange={handleEssayChange} placeholder="Develop your thinking here — let the evidence guide you. Rerum cognoscere causas." />
          </div>
        </div>

        {/* RIGHT — field notes from sources */}
        <div style={{ overflow: 'auto', padding: '20px 24px', background: isDark ? '#18140e' : '#f5f0e4' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 14 }}>
            <div style={{ fontSize: 8, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.12em', textTransform: 'uppercase' }}>
              Field notes from sources
            </div>
            <button onClick={() => setShowAttachPicker(p => !p)}
              style={{ fontSize: 9, padding: '3px 10px', borderRadius: 2, background: showAttachPicker ? 'var(--accent)' : 'transparent', color: showAttachPicker ? 'var(--paper-card)' : 'var(--ink-3)', border: '1px solid var(--paper-3)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.06em' }}>
              {showAttachPicker ? 'DONE' : '+ ATTACH NOTE'}
            </button>
          </div>

          {showAttachPicker && (
            <div style={{ background: 'var(--paper-2)', border: '1px solid var(--paper-3)', borderRadius: 2, padding: '10px 12px', marginBottom: 14 }}>
              <input autoFocus value={attachSearch} onChange={e => setAttachSearch(e.target.value)}
                placeholder="Search field notes…" style={{ width: '100%', padding: '5px 8px', fontSize: 12, marginBottom: 8, borderRadius: 2, fontStyle: 'italic' }} />
              <div style={{ maxHeight: 200, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 4 }}>
                {unattached.slice(0, 15).map(t => {
                  const b = books.find(bk => bk.id === t.bookId);
                  return (
                    <div key={t.id} onClick={() => handleAttach(t.id)}
                      style={{ padding: '6px 10px', borderRadius: 2, cursor: 'pointer', background: 'var(--paper-card)', border: '1px solid var(--paper-3)', fontSize: 12, color: 'var(--ink)', lineHeight: 1.5 }}
                      onMouseEnter={e => e.currentTarget.style.borderColor = 'var(--accent-2)'}
                      onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--paper-3)'}>
                      <span style={{ color: b?.color, fontSize: 10, fontStyle: 'italic', display: 'block', marginBottom: 2 }}>{b?.title}</span>
                      {(t.text || '').replace(/<[^>]+>/g, '').slice(0, 100)}{(t.text || '').length > 100 ? '…' : ''}
                    </div>
                  );
                })}
                {unattached.length === 0 && <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic' }}>No further notes available to attach.</div>}
              </div>
            </div>
          )}

          {byBook.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '40px 0', color: 'var(--ink-4)' }}>
              <div style={{ fontSize: 32, opacity: 0.1, marginBottom: 10, fontFamily: 'var(--font-display)', lineHeight: 1 }}>◌</div>
              <div style={{ fontSize: 12, fontStyle: 'italic', lineHeight: 1.75 }}>No field notes attached yet.<br/>
                <span style={{ fontSize: 10, fontFamily: 'var(--font-mono)', fontStyle: 'normal', opacity: 0.5 }}>Use + ATTACH NOTE to file evidence.</span>
              </div>
            </div>
          ) : byBook.map(({ book, thoughts: bThoughts }) => (
            <div key={book?.id} style={{ marginBottom: 22 }}>
              {/* Source header */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 10, paddingBottom: 6, borderBottom: `2px solid ${book?.color}33` }}>
                <div style={{ width: 8, height: 8, borderRadius: '50%', background: book?.color, boxShadow: `0 0 0 2px ${book?.color}33` }} />
                <span style={{ fontSize: 12, fontWeight: 600, color: book?.color, fontStyle: 'italic', fontFamily: 'var(--font-display)', flex: 1 }}>{book?.title}</span>
                {book?.author && <span style={{ fontSize: 10, color: 'var(--ink-4)', fontStyle: 'italic' }}>{book.author}</span>}
              </div>
              {bThoughts.map(t => (
                <FieldNoteCard key={t.id} thought={t} book={book} thoughtTypes={thoughtTypes} onDetach={handleDetach} />
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
